 let selected=List.map (fun p->LIR.Physical p) [LIR.X0;LIR.X3;LIR.X7;LIR.X8;LIR.X19]@[LIR.Virtual (-1)] in
 let sizes=[-2147483648;-32769;-1;0;8;32768;2147483647] in
