 let operands=List.map (fun reg->LIR.Reg reg) gps@List.map (fun n->LIR.StackSlot n) sizes@List.map (fun n->LIR.Imm n) imms@[LIR.FloatImm (-0.);LIR.FloatImm (Int64.float_of_bits 0xfff8000000000000L);LIR.FloatSymbol 0.1;LIR.FloatSymbol (Int64.float_of_bits 0x7ff8000000000001L);LIR.FloatSymbol (Int64.float_of_bits 0x7ff0000000000001L);LIR.StringSymbol source;LIR.StringSymbol "hé😀";LIR.StringSymbol (HostText.ofScalars [|0xfffd;0x61;0xfffd|]);LIR.FuncAddr (AST.functionId 0L);LIR.FuncAddr (AST.functionId 2L);LIR.FuncAddr (AST.functionId (-1L))] in
 let ctx enabled={X64CodeGenTypes.functionName=source;stackSize=32;usedCalleeSaved=[LIR.X19;LIR.X20];enableLeakCheck=enabled;recordRegistry=StringOrder.Map.empty;sumShapeRegistry=StringOrder.Map.empty;functionNames=FunctionIdMap.ofList [AST.functionId 0L,source;AST.functionId (-1L),"largest"]} in
 let c=ctx false in
